if mibBuilder.loadTexts: cwmIngressSCTFileName.setDescription('This variable contains the SCT filename. Write access\n        is not required. The filename has cwmIngressSCTFileId\n        value as the suffix. For example, the value SCT.INGR.13\n        for this object indicates 13 is the value of\n        cwmIngressSCTFileId.')
cwmAutoLineDiagEnable = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 145, 1, 1, 1, 1, 4), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2))).clone('disable')).setMaxAccess("readwrite")
